<summary>Standalone Node.js reproduction (no dependencies or API credentials)</summary>

Save as `repro.mjs`, then run `node repro.mjs /absolute/path/to/codex`. It creates a temporary home, uses one loopback mock response, and stops only its two app-server children. The temporary home is retained for inspection.

```javascript
import { execFileSync, spawn } from 'node:child_process';
import fs from 'node:fs';
import http from 'node:http';
import os from 'node:os';
import path from 'node:path';
import readline from 'node:readline';

if (!process.argv[2]) {
  console.error('Usage: node /tmp/codex-yolo-cold-resume-repro.mjs <codex-binary>');
  process.exit(2);
}
const codex = path.resolve(process.argv[2]);
fs.accessSync(codex, fs.constants.X_OK);
const codexVersion = execFileSync(codex, ['--version'], { encoding: 'utf8' }).trim();
const home = fs.mkdtempSync(path.join(os.tmpdir(), 'codex-yolo-cold-resume-'));
const cwd = path.join(home, 'workspace');
fs.mkdirSync(cwd);
fs.mkdirSync(path.join(home, 'tmp'));
let mockResponseCount = 0;
const sse = [
  { type: 'response.created', response: { id: 'mock-response' } },
  {
    type: 'response.output_item.done',
    item: {
      type: 'message',
      role: 'assistant',
      id: 'mock-message',
      content: [{ type: 'output_text', text: 'mocked' }],
    },
  },
  {
    type: 'response.completed',
    response: {
      id: 'mock-response',
      usage: {
        input_tokens: 0,
        input_tokens_details: null,
        output_tokens: 0,
        output_tokens_details: null,
        total_tokens: 0,
      },
    },
  },
].map((event) => `data: ${JSON.stringify(event)}\n\n`).join('') + 'data: [DONE]\n\n';
const mock = http.createServer((request, response) => {
  if (!request.url?.endsWith('/responses')) {
    response.writeHead(200, { 'content-type': 'application/json' });
    response.end('[]');
    return;
  }
  mockResponseCount += 1;
  request.resume();
  request.on('end', () => {
    response.writeHead(200, { 'content-type': 'text/event-stream', 'cache-control': 'no-cache' });
    response.end(sse);
  });
});

function launchAppServer() {
  const child = spawn(codex, ['app-server', '--listen', 'stdio://'], {
    cwd,
    env: {
      PATH: process.env.PATH,
      HOME: home,
      CODEX_HOME: home,
      CODEX_APP_SERVER_MANAGED_CONFIG_PATH: path.join(home, 'managed_config.toml'),
      TMPDIR: path.join(home, 'tmp'),
      RUST_LOG: 'error',
    },
    stdio: ['pipe', 'pipe', 'pipe'],
  });
  const lines = readline.createInterface({ input: child.stdout });
  const pending = new Map();
  const notifications = [];
  const notificationWaiters = [];
  let stderr = '';
  let nextId = 1;
  child.stderr.on('data', (chunk) => { stderr += chunk.toString(); });
  lines.on('line', (line) => {
    let message;
    try { message = JSON.parse(line); } catch { return; }
    if (message.id != null && pending.has(message.id)) {
      const waiter = pending.get(message.id);
      pending.delete(message.id);
      waiter.resolve(message);
      return;
    }
    if (!message.method) return;
    notifications.push(message);
    const index = notificationWaiters.findIndex((waiter) => waiter.method === message.method);
    if (index >= 0) notificationWaiters.splice(index, 1)[0].resolve(message);
  });
  return {
    child,
    request(method, params) {
      const id = nextId++;
      const result = new Promise((resolve, reject) => {
        const timeout = setTimeout(() => {
          pending.delete(id);
          reject(new Error(`timed out waiting for ${method}; stderr=${stderr}`));
        }, 20000);
        pending.set(id, {
          resolve: (message) => { clearTimeout(timeout); resolve(message); },
        });
      });
      child.stdin.write(`${JSON.stringify({ jsonrpc: '2.0', id, method, params })}\n`);
      return result;
    },
    notify(method) {
      child.stdin.write(`${JSON.stringify({ jsonrpc: '2.0', method })}\n`);
    },
    waitForNotification(method) {
      const index = notifications.findIndex((message) => message.method === method);
      if (index >= 0) return Promise.resolve(notifications.splice(index, 1)[0]);
      return new Promise((resolve, reject) => {
        const timeout = setTimeout(() => reject(new Error(`timed out waiting for ${method}; stderr=${stderr}`)), 20000);
        notificationWaiters.push({
          method,
          resolve: (message) => { clearTimeout(timeout); resolve(message); },
        });
      });
    },
    stop() {
      return new Promise((resolve) => {
        child.once('exit', (code, signal) => resolve({ code, signal, stderr }));
        child.kill('SIGTERM');
      });
    },
  };
}

async function rpc(server, method, params) {
  const message = await server.request(method, params);
  if (message.error) throw new Error(`${method}: ${JSON.stringify(message.error)}`);
  return message.result;
}

async function initialize(server) {
  await rpc(server, 'initialize', {
    clientInfo: { name: 'isolated-yolo-repro', version: '1' },
    capabilities: { experimentalApi: true },
  });
  server.notify('initialized');
}

function rolloutTurnContext() {
  const files = [];
  const visit = (directory) => {
    if (!fs.existsSync(directory)) return;
    for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
      const entryPath = path.join(directory, entry.name);
      if (entry.isDirectory()) visit(entryPath);
      else if (entry.name.startsWith('rollout-') && entry.name.endsWith('.jsonl')) files.push(entryPath);
    }
  };
  visit(path.join(home, 'sessions'));
  for (const file of files) {
    for (const line of fs.readFileSync(file, 'utf8').split('\n')) {
      if (!line) continue;
      const record = JSON.parse(line);
      if (record.type === 'turn_context') {
        return {
          approvalPolicy: record.payload.approval_policy,
          sandboxPolicy: record.payload.sandbox_policy,
          permissionProfile: record.payload.permission_profile,
          activePermissionProfile: record.payload.active_permission_profile ?? null,
        };
      }
    }
  }
  throw new Error('no persisted turn_context found');
}

let first;
let second;
(async () => {
  await new Promise((resolve) => mock.listen(0, '127.0.0.1', resolve));
  const providerUrl = `http://127.0.0.1:${mock.address().port}/v1`;
  fs.writeFileSync(path.join(home, 'config.toml'), [
    'model = "mock-model"',
    'model_provider = "mock"',
    'approval_policy = "on-request"',
    'sandbox_mode = "workspace-write"',
    '',
    '[model_providers.mock]',
    'name = "loopback mock"',
    `base_url = "${providerUrl}"`,
    'wire_api = "responses"',
    'requires_openai_auth = false',
    '',
  ].join('\n'));
  fs.writeFileSync(path.join(home, 'managed_config.toml'), '');

  first = launchAppServer();
  await initialize(first);
  const started = await rpc(first, 'thread/start', {
    cwd,
    model: 'mock-model',
    modelProvider: 'mock',
    approvalPolicy: 'never',
    sandbox: 'danger-full-access',
  });
  await first.waitForNotification('thread/started');
  await rpc(first, 'turn/start', {
    threadId: started.thread.id,
    input: [{ type: 'text', text: 'reply with mocked output' }],
  });
  await first.waitForNotification('turn/completed');
  const persistedContext = rolloutTurnContext();
  const firstExit = await first.stop();
  first = null;

  second = launchAppServer();
  await initialize(second);
  const resumed = await rpc(second, 'thread/resume', {
    threadId: started.thread.id,
    excludeTurns: true,
  });
  const secondExit = await second.stop();
  second = null;
  mock.close();

  const summary = {
    codexVersion,
    appServerExitCodes: [firstExit.code, secondExit.code],
    localMockResponses: mockResponseCount,
    startResponse: {
      approvalPolicy: started.approvalPolicy,
      sandboxType: started.sandbox.type,
      activePermissionProfile: started.activePermissionProfile ?? null,
    },
    persistedTurnContext: {
      approvalPolicy: persistedContext.approvalPolicy,
      sandboxType: persistedContext.sandboxPolicy.type,
      permissionProfileType: persistedContext.permissionProfile.type,
      activePermissionProfile: persistedContext.activePermissionProfile,
    },
    coldResumeResponse: {
      approvalPolicy: resumed.approvalPolicy,
      sandboxType: resumed.sandbox.type,
      activePermissionProfile: resumed.activePermissionProfile ?? null,
    },
  };
  if (summary.appServerExitCodes.some((code) => code !== 0)) throw new Error(`unclean exit: ${JSON.stringify(summary)}`);
  if (summary.localMockResponses !== 1) throw new Error(`expected one loopback response: ${JSON.stringify(summary)}`);
  if (summary.startResponse.sandboxType !== 'dangerFullAccess') throw new Error(`unexpected start settings: ${JSON.stringify(summary)}`);
  if (summary.persistedTurnContext.sandboxType !== 'danger-full-access') throw new Error(`unexpected persisted settings: ${JSON.stringify(summary)}`);
  if (summary.coldResumeResponse.sandboxType !== 'workspaceWrite') throw new Error(`expected reproduced downgrade: ${JSON.stringify(summary)}`);
  console.log(JSON.stringify(summary, null, 2));
})().catch(async (error) => {
  if (first?.child && first.child.exitCode == null) await first.stop();
  if (second?.child && second.child.exitCode == null) await second.stop();
  mock.close();
  console.error(error.stack || error);
  process.exitCode = 1;
});

```

Verified output on the installed binary:

